const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    let idx = 0;

    const n = parseInt(input[idx++]);
    const b = parseInt(input[idx++]);
    const a = [];
    for (let i = 0; i < n; i++) {
        a.push(parseInt(input[idx++]));
    }

    let even = 0;
    let odd = 0;
    const possibleCuts = [];

    for (let i = 0; i < n; i++) {
        if (a[i] % 2 === 0) {
            even++;
        } else {
            odd++;
        }
        if (even === odd && i + 1 < n) {
            possibleCuts.push(Math.abs(a[i] - a[i + 1]));
        }
    }

    if (even !== odd) {
        console.log(0);
        return;
    }

    possibleCuts.sort((x, y) => x - y);

    let ans = 0;
    let sum = 0;
    for (const cost of possibleCuts) {
        if (sum + cost <= b) {
            sum += cost;
            ans++;
        } else {
            break;
        }
    }

    console.log(ans);
}

